import {readInvoices,deleteInvoice} from './invoice-store.mjs';
import {invoiceDate} from './invoice-core.mjs';
import {invoicePdf} from './invoice-pdf.mjs';
import {invoiceWhatsAppParts,invoiceShareText,canShareInvoiceFile} from './invoice-share.mjs';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US').format(n);
let current=null,pdfUrl=null,pdfFile=null,renderVersion=0;
function toast(s){$('#invoiceToast').textContent=s;$('#invoiceToast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#invoiceToast').classList.remove('show'),5000);}
function paperReceipt(){return `<section class="receipt"><h2>التسليم والاستلام</h2><p class="intro">تُملأ بالقلم على النسخة المطبوعة عند استلام المنتجات.</p><p class="paper-line">تاريخ التسليم: ........ / ........ / ................</p><p class="paper-line">ملاحظات الاستلام: ................................................................................</p><div class="signature-grid">${['ممثل المستودع / المُسلّم','ممثل الصيدلية / المستلم'].map(title=>`<div class="signature-box paper-signature"><h3>${title}</h3><p>الاسم: ........................................</p><div class="pen-signature">التوقيع بالقلم:<span></span></div><p>الختم: ........................................</p></div>`).join('')}</div></section>`;}
function render(){const version=++renderVersion;if(pdfUrl)URL.revokeObjectURL(pdfUrl);pdfUrl=null;pdfFile=null;const list=readInvoices(),id=location.hash.slice(1);current=list.find(i=>i.id===id)||null;
if(!current){$('#invoiceRoot').innerHTML=`<div class="history-head"><h1>فواتيري على هذا الجهاز</h1><p class="muted">نسخ الطلبات الجاهزة للمشاركة والطباعة.</p></div><p class="local-note">الحفظ على هذا الجهاز فقط. حمّل PDF للاحتفاظ بنسخة. مسح بيانات المتصفح يحذف الأرشيف المحلي.</p>${id?'<div class="invoice-error">هذه الفاتورة غير موجودة على هذا الجهاز. افتحها من الجهاز الذي أصدرها، أو استخدم نسخة PDF المحفوظة.</div>':''}${list.length?`<div class="history-list">${list.map(i=>`<article class="history-card"><div><h2>${esc(i.pharmacy.name)}</h2><p dir="ltr">${i.id}</p><p>${invoiceDate(i.createdAt)} · ${i.items.length} صنف · ${money(i.total)} ل.س</p><span class="status">التوقيع بالقلم بعد الطباعة</span></div><div class="actions"><a class="btn primary" href="#${i.id}">عرض ومشاركة PDF</a><button class="btn danger" data-delete="${i.id}">حذف من الجهاز</button></div></article>`).join('')}</div>`:'<div class="empty-invoices"><span>▤</span><h2>فاتورتك الأولى تبدأ من السلة</h2><p>اختر المنتجات والكميات، وأدخل بيانات الصيدلية، ثم جهّز الطلب ونسخة PDF.</p><a href="index.html#catalog" class="btn primary">تصفّح المنتجات</a></div>'}`;
document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('هل حمّلت نسخة؟ سيُحذف هذا السجل من هذا الجهاز.')){try{deleteInvoice(b.dataset.delete);render();}catch{toast('تعذّر حذف السجل.');}}});return;}
const i=current,wa=invoiceWhatsAppParts(i);
$('#invoiceRoot').innerHTML=`<div class="toolbar"><a href="invoice.html" class="btn">← جميع فواتيري</a><div><a href="index.html?edit=${i.id}" class="btn">تعديل الطلب</a><button id="printInvoice" class="btn">طباعة</button><a id="downloadPdf" class="btn disabled-link" aria-disabled="true">جارٍ تجهيز PDF…</a></div></div>
<section class="order-ready"><span class="ready-label">طلب الصيدلية</span><h2>بيانات الطلب ونسخة PDF في مكان واحد</h2><p>رقم واتساب المستودع المعتمد: <b dir="ltr">+963967765704</b></p><div class="ready-actions"><button id="sharePdf" class="btn primary" disabled>جارٍ تجهيز PDF للمشاركة…</button><button id="copyWarehouse" class="btn">نسخ رقم المستودع</button></div><p id="shareHelp" class="share-help">يجري تجهيز الملف…</p><p id="pdfError" class="invoice-error" role="alert" hidden></p><div class="whatsapp-message"><h3>فتح رسالة الطلب على رقم المستودع</h3><div>${wa.map((p,n)=>`<a class="btn whatsapp-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">${wa.length===1?'فتح الطلب في واتساب ↗':`فتح الجزء ${n+1} من ${wa.length} في واتساب ↗`}</a>`).join('')}</div><p>${wa.length>1?'الطلب طويل؛ أرسل الأجزاء كلها. ':''}هذا الزر يفتح رسالة الأصناف والكميات؛ ملف PDF لا يُرفق تلقائيًا. أرفقه من زر المشاركة أو بعد تحميله.</p></div><p class="send-status">لم يُرسل الطلب من الموقع. اختر المستودع واضغط «إرسال» داخل واتساب لإتمامه.</p></section>
<p class="local-note">التوقيع بالقلم لاحقًا على الفاتورة المطبوعة. اسم المُسلّم والمستلم والتاريخ والتوقيع والختم تُترك فارغة. هذه النسخة محفوظة على جهازك فقط.</p>
<article class="invoice-paper"><div class="paper-heading"><div><h1>مستودع العاصمة</h1><h2>فاتورة طلب مبدئية</h2><p>واتساب الطلبات: <b dir="ltr">+963967765704</b></p></div><div class="invoice-number"><b>${i.id}</b><time>${invoiceDate(i.createdAt)}</time><br><span class="status">تحتاج تأكيد المستودع</span></div></div><section class="pharmacy-box"><span class="label">الصيدلية الطالبة</span><h3>${esc(i.pharmacy.name)}</h3><p><strong>العنوان</strong>${esc([i.pharmacy.city,i.pharmacy.address].filter(Boolean).join(' - '))}</p>${i.pharmacy.phone?`<p><strong>الهاتف</strong><bdi>${esc(i.pharmacy.phone)}</bdi></p>`:''}${i.pharmacy.contact?`<p><strong>المسؤول</strong>${esc(i.pharmacy.contact)}</p>`:''}</section>${i.previousId?`<p class="revision-note">نسخة معدّلة من الطلب ${esc(i.previousId)}</p>`:''}<div class="table-scroll"><table><thead><tr><th>#</th><th>الصنف</th><th>الكمية</th><th>سعر الوحدة</th><th>الإجمالي</th></tr></thead><tbody>${i.items.map((p,n)=>`<tr><td>${n+1}</td><td class="item-name"><strong>${esc(p.ar)}</strong><small lang="en" dir="ltr">${esc(p.en)} · ${p.id}</small></td><td class="num">${p.qty}</td><td class="num">${money(p.unitPrice)}</td><td class="num">${money(p.total)}</td></tr>`).join('')}</tbody></table></div><div class="totals"><span>الإجمالي التقديري<small>${i.items.length} صنف · ${i.count} قطعة</small></span><div><b>${money(i.total)}</b> <small>ل.س</small></div></div><p class="muted">الأسعار والتوفر تحتاج تأكيد المستودع. الإجمالي لا يشمل التوصيل. لا تُعد هذه الفاتورة إثباتًا للدفع.</p>${i.pharmacy.notes?`<p class="notes"><b>ملاحظات الطلب</b><br>${esc(i.pharmacy.notes)}</p>`:''}${paperReceipt()}<div class="invoice-footer">${i.id} · مستودع العاصمة · نسخة طلب للطباعة</div></article>`;
$('#printInvoice').onclick=()=>window.print();
$('#copyWarehouse').onclick=async()=>{try{await navigator.clipboard.writeText('+963967765704');toast('نُسخ رقم المستودع.');}catch{toast('رقم المستودع: +963967765704');}};
$('#sharePdf').onclick=()=>sharePreparedFile(i);
preparePdf(i,version);
}
async function preparePdf(invoice,version){try{const blob=await invoicePdf(invoice);if(version!==renderVersion)return;pdfFile=new File([blob],invoice.id+'.pdf',{type:'application/pdf'});pdfUrl=URL.createObjectURL(pdfFile);const a=$('#downloadPdf');a.href=pdfUrl;a.download=pdfFile.name;a.textContent='↓ تحميل PDF';a.classList.remove('disabled-link');a.removeAttribute('aria-disabled');const share=$('#sharePdf');if(canShareInvoiceFile(pdfFile)){share.disabled=false;share.textContent='مشاركة الطلب وملف PDF';$('#shareHelp').textContent='اختر واتساب من قائمة المشاركة، ثم المستودع على الرقم أعلاه وأكّد الإرسال. ملف PDF يتضمن كامل بيانات الصيدلية والأصناف والكميات.';}else{share.hidden=true;$('#shareHelp').textContent='مشاركة الملفات غير متاحة في هذا المتصفح. حمّل PDF، ثم افتح الطلب في واتساب وأرفق الملف قبل الإرسال.';}}catch{$('#downloadPdf').hidden=true;$('#sharePdf').hidden=true;$('#shareHelp').textContent='يمكنك فتح الطلب في واتساب واستخدام الطباعة للحفظ بصيغة PDF.';$('#pdfError').hidden=false;$('#pdfError').textContent='تعذّر تجهيز PDF. استخدم زر الطباعة ثم «حفظ كـ PDF».';}}
function sharePreparedFile(invoice){if(!canShareInvoiceFile(pdfFile))return;const b=$('#sharePdf');b.disabled=true;let pending;try{pending=navigator.share({files:[pdfFile],title:'طلب '+invoice.pharmacy.name,text:invoiceShareText(invoice)});}catch(e){shareFailed(e);b.disabled=false;return;}Promise.resolve(pending).then(()=>toast('أكمل الإرسال في التطبيق الذي اخترته؛ الموقع لا يؤكد وصول الطلب.')).catch(shareFailed).finally(()=>{b.disabled=false;});}
function shareFailed(error){toast(error?.name==='AbortError'?'أُلغيت المشاركة؛ يمكنك المحاولة مجددًا.':'تعذّرت المشاركة. حمّل PDF وأرفقه في واتساب.');}
window.addEventListener('hashchange',render);render();
